#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const ll MOD = 998244353;

ll power(ll x, ll y) {
    ll result = 1;
    x %= MOD;

    while (y > 0) {
        if (y & 1) result = result * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }

    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m;
    cin >> n >> m;

    ll exponent = ((n + m) % 2 == 0) ? n + m : n + m - 1;
    cout << power(2, exponent);

    return 0;
}

